-- Owned progression schema; explicit migration after canonical authority/accounts.
CREATE TABLE IF NOT EXISTS owned_progression_definitions (
 kind text NOT NULL CHECK(kind IN('achievement','quest')),identifier text NOT NULL,
 definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),updated_at timestamptz NOT NULL,
 PRIMARY KEY(kind,identifier)
);
CREATE TABLE IF NOT EXISTS owned_progression_events (
 account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),event_key text NOT NULL,kind text NOT NULL,source_id text NOT NULL,occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL,
 PRIMARY KEY(account_id,event_key)
);
CREATE TABLE IF NOT EXISTS owned_progression_progress (
 account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),kind text NOT NULL,identifier text NOT NULL,period_key text NOT NULL DEFAULT '',
 progress_count integer NOT NULL DEFAULT 0 CHECK(progress_count>=0),current_streak integer NOT NULL DEFAULT 0,best_streak integer NOT NULL DEFAULT 0,last_progress_at timestamptz,completed_at timestamptz,
 PRIMARY KEY(account_id,kind,identifier,period_key),FOREIGN KEY(kind,identifier)REFERENCES owned_progression_definitions(kind,identifier)
);
CREATE TABLE IF NOT EXISTS owned_progression_grants (
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),kind text NOT NULL,identifier text NOT NULL,title text NOT NULL,
 reward_token text NOT NULL UNIQUE,source_event_id text NOT NULL,period_key text NOT NULL,reward jsonb NOT NULL,
 badge_granted_at timestamptz,experience_granted_at timestamptz,source_points_granted_at timestamptz,notification_sent_at timestamptz,
 created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(account_id,kind,identifier,period_key)
);
CREATE TABLE IF NOT EXISTS owned_progression_experience (
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),reason_type text NOT NULL,reason text NOT NULL,
 delta bigint NOT NULL CHECK(delta>=0),bonus_multiplier numeric NOT NULL DEFAULT 1 CHECK(bonus_multiplier=1),reward_token text NOT NULL UNIQUE,created_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS owned_progression_experience_history ON owned_progression_experience(account_id,created_at DESC,id);
CREATE TABLE IF NOT EXISTS owned_progression_badges (
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),type text NOT NULL,label text,caption text,meta jsonb NOT NULL DEFAULT '{}',
 expired_at timestamptz,activated_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,deleted_at timestamptz,
 UNIQUE(account_id,type),CHECK(jsonb_typeof(meta)='object')
);
CREATE UNIQUE INDEX IF NOT EXISTS owned_progression_one_active_badge ON owned_progression_badges(account_id)WHERE activated_at IS NOT NULL AND deleted_at IS NULL;
-- Display badges never confer identity permissions. Retain manual provenance
-- independently of editable labels/meta and the earned reward ledger.
ALTER TABLE owned_progression_badges ADD COLUMN IF NOT EXISTS origin text NOT NULL DEFAULT 'progression' CHECK(origin IN('progression','admin'));
ALTER TABLE owned_progression_badges ADD COLUMN IF NOT EXISTS granted_by uuid REFERENCES owned_authority_accounts(id) CONSTRAINT owned_progression_badge_provenance CHECK((origin='admin')=(granted_by IS NOT NULL));
CREATE TABLE IF NOT EXISTS owned_progression_checkins (
 id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),day date NOT NULL,level integer NOT NULL CHECK(level BETWEEN 0 AND 4),
 reward_experience bigint NOT NULL CHECK(reward_experience=100),created_at timestamptz NOT NULL,
 UNIQUE(account_id,day),CHECK(day=(created_at AT TIME ZONE 'UTC')::date)
);
CREATE TABLE IF NOT EXISTS owned_progression_level_policy(id integer PRIMARY KEY CHECK(id=1),thresholds jsonb NOT NULL CHECK(jsonb_typeof(thresholds)='array'),updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS owned_progression_audit(id bigserial PRIMARY KEY,actor_id uuid NOT NULL REFERENCES owned_authority_accounts(id),action text NOT NULL,target text NOT NULL,occurred_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS owned_progression_outbox(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),grant_id uuid NOT NULL UNIQUE REFERENCES owned_progression_grants(id),packet_type text NOT NULL CHECK(packet_type='progression.completed'),payload jsonb NOT NULL,created_at timestamptz NOT NULL,delivered_at timestamptz);

-- Licensed catalog values from ProgressionCatalogDefaults.cs at pinned 4ee2d0c.
-- Action/mode/schedule encodings are explicitly owned; source-point currency is not inferred.
CREATE TABLE IF NOT EXISTS owned_progression_projection_receipts (
 kind text NOT NULL,account_id uuid NOT NULL REFERENCES owned_authority_accounts(id),source_id uuid NOT NULL,
 processed_at timestamptz NOT NULL,outcome text NOT NULL CHECK(outcome IN('applied','gone','disabled')),
 PRIMARY KEY(kind,account_id,source_id)
);
